var STATE_HELD = 4;
var STATE_SUSPENDED = 2;
function Box(v) { this.v = v; }
Box.prototype.get = function () { return this.v; };
function method(o) { const r = o.get(); return r; }
function make(v) { const b = new Box(v); return b; }
function Vec(x, y, z) { this.x = x; this.y = y; this.z = z; }
Vec.prototype.dot = function (other) { return this.x * other.x + this.y * other.y + this.z * other.z; };
function dot(a, b) { return a.dot(b); }
function Base() {}
Base.prototype.deepGet = function () { return 7; };
function Mid() {}
Mid.prototype = Object.create(Base.prototype);
function Sub() {}
Sub.prototype = Object.create(Mid.prototype);
function callDeep(s) { return s.deepGet(); }
function Task(state, next) { this.state = state; this.next = next; }
Task.prototype.isHeldOrSuspended = function () {
  return (this.state & STATE_HELD) != 0 || this.state == STATE_SUSPENDED;
};
function walk(t) {
  let n = 0;
  for (let cur = t; cur != null; cur = cur.next) if (cur.isHeldOrSuspended()) n++;
  return n;
}
function setState(t, v) { t.state = v; return v; }
export function run() {
  let s = 0;
  const o = new Box(1);
  const a = new Vec(1, 2, 3), b = new Vec(4, 5, 6);
  const sub = new Sub();
  const t = new Task(0, new Task(4, new Task(2, null)));
  for (let i = 0; i < 1000; i++) {
    s += method(o) + make(i).v + dot(a, b) + callDeep(sub) + walk(t) + setState(t, i & 1);
  }
  return s > 0 ? 42 : 1;
}
